target.css:
:root {
  --ink: #20232a;
  --paper: #fffaf1;
  --ember: #ed5c35;
  --amber: #f6ad38;
  --mint: #5cae91;
  --mist: #dce6e1;
  --line: #c9c6bb;
  --muted: #6f6e69;
}

.furnace {
  box-sizing: border-box;
  width: 500px;
  padding: 16px;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 11px;
}

.panel-head section,
.heat,
.thermo,
.range,
.panel-foot p {
  margin: 0;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

h1 {
  margin: 0;
  font-size: 23px;
  line-height: 1;
  letter-spacing: -0.7px;
}

.live {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  padding: 6px 8px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.live span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ember);
}

.heat {
  display: grid;
  grid-template-columns: 142px 1fr 100px;
  align-items: center;
  gap: 12px;
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--mist);
}

.thermo p,
.range {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.thermo strong {
  display: block;
  margin-top: 2px;
  color: var(--ember);
  font-size: 25px;
  line-height: 1;
  letter-spacing: -1px;
}

.thermo small {
  margin-left: 2px;
  font-size: 12px;
  letter-spacing: 0;
}

.gauge {
  position: relative;
  height: 14px;
  overflow: hidden;
  border: 2px solid var(--ink);
  border-radius: 999px;
  background: var(--paper);
}

.gauge-fill {
  display: block;
  width: 78%;
  height: 100%;
  background: var(--amber);
}

.gauge-mark {
  position: absolute;
  z-index: 1;
  top: 0;
  width: 2px;
  height: 100%;
  background: var(--ink);
}

.gauge-mark.one { left: 33%; }
.gauge-mark.two { left: 66%; }
.gauge-mark.three { right: 0; }

.range {
  line-height: 1.35;
  text-align: right;
}

.range b {
  color: var(--ink);
  font-size: 10px;
}

.stations {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 10px;
}

.station {
  display: grid;
  grid-template-columns: 28px 1fr;
  align-items: center;
  gap: 2px 7px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--paper);
  color: var(--ink);
  text-align: left;
}

.station-icon {
  grid-row: span 2;
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border-radius: 7px;
  font-size: 18px;
}

.station strong {
  font-size: 10px;
  line-height: 1;
  letter-spacing: 0.4px;
}

.station em {
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.ready .station-icon { background: var(--mint); color: var(--paper); }
.ready em { color: var(--mint); }
.active { border-color: var(--ember); }
.active .station-icon { background: var(--ember); color: var(--paper); }
.active em { color: var(--ember); }
.idle .station-icon { background: var(--mist); color: var(--muted); }
.idle em { color: var(--muted); }

.panel-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
}

.panel-foot p {
  font-size: 11px;
  font-weight: 600;
}

.panel-foot p span {
  margin-right: 5px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.shift-button {
  padding: 6px 9px;
  border: 1px solid var(--ink);
  border-radius: 6px;
  background: var(--paper);
  color: var(--ink);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

